 1→'use client'
 2→
 3→import { motion } from 'motion/react'
 4→import { clsx } from 'clsx'
 5→
 6→interface ButtonProps {
 7→  children: React.ReactNode
 8→  variant?: 'primary' | 'secondary' | 'danger' | 'success' | 'ghost'
 9→  size?: 'sm' | 'md' | 'lg'
10→  disabled?: boolean
11→  onClick?: () => void
12→  className?: string
13→  type?: 'button' | 'submit'
14→}
15→
16→const variantStyles = {
17→  primary: 'bg-nebula/20 border-nebula/40 text-nebula hover:bg-nebula/30 hover:border-nebula/60',
18→  secondary: 'bg-glass border-glass-border text-starlight hover:bg-glass-hover',
19→  danger: 'bg-terracotta/20 border-terracotta/40 text-terracotta hover:bg-terracotta/30',
20→  success: 'bg-signal/20 border-signal/40 text-signal hover:bg-signal/30',
21→  ghost: 'bg-transparent border-transparent text-starlight-dim hover:text-starlight hover:bg-glass',
22→}
23→
24→const sizeStyles = {
25→  sm: 'px-3 py-1.5 text-sm',
26→  md: 'px-5 py-2.5 text-base',
27→  lg: 'px-8 py-3.5 text-lg',
28→}
29→
30→export function Button({ children, variant = 'primary', size = 'md', disabled, onClick, className, type = 'button' }: ButtonProps) {
31→  return (
32→    <motion.button
33→      type={type}
34→      onClick={onClick}
35→      disabled={disabled}
36→      className={clsx(
37→        'font-display uppercase tracking-wider border rounded-xl backdrop-blur-sm transition-colors',
38→        'focus:outline-none focus-visible:ring-2 focus-visible:ring-nebula/50',
39→        variantStyles[variant],
40→        sizeStyles[size],
41→        disabled && 'opacity-40 cursor-not-allowed',
42→        className
43→      )}
44→      whileHover={disabled ? undefined : { scale: 1.03 }}
45→      whileTap={disabled ? undefined : { scale: 0.97 }}
46→      transition={{ type: 'spring', stiffness: 400, damping: 25 }}
47→    >
48→      {children}
49→    </motion.button>
50→  )
51→}
