  1→'use client'
  2→
  3→import { useState, useCallback, useMemo } from 'react'
  4→import { motion, AnimatePresence } from 'motion/react'
  5→import { clsx } from 'clsx'
  6→import { GlassPanel, TypewriterText, Button } from '@/components/ui'
  7→import { crewMembers } from '@/lib/data/crew'
  8→import type { CrewMemberDef } from '@/lib/data/crew'
  9→import type { DialogueNode, DialogueChoice } from '@/lib/types'
 10→
 11→interface DialogueSystemProps {
 12→  nodes: DialogueNode[]
 13→  onComplete: (score: number) => void
 14→  className?: string
 15→}
 16→
 17→type FeedbackState = {
 18→  type: 'correct' | 'wrong'
 19→  response?: string
 20→} | null
 21→
 22→function getSpeaker(speakerId: string): CrewMemberDef | null {
 23→  return crewMembers.find((c) => c.id === speakerId) ?? null
 24→}
 25→
 26→export function DialogueSystem({ nodes, onComplete, className }: DialogueSystemProps) {
 27→  const [currentIndex, setCurrentIndex] = useState(0)
 28→  const [textComplete, setTextComplete] = useState(false)
 29→  const [feedback, setFeedback] = useState<FeedbackState>(null)
 30→  const [correctCount, setCorrectCount] = useState(0)
 31→  const [showSummary, setShowSummary] = useState(false)
 32→
 33→  const totalQuestions = useMemo(
 34→    () => nodes.filter((n) => n.choices && n.choices.length > 0).length,
 35→    [nodes]
 36→  )
 37→
 38→  const currentNode = nodes[currentIndex] as DialogueNode | undefined
 39→  const speaker = currentNode ? getSpeaker(currentNode.speaker) : null
 40→
 41→  const advanceToNext = useCallback(() => {
 42→    const nextIndex = currentIndex + 1
 43→    if (nextIndex >= nodes.length) {
 44→      setShowSummary(true)
 45→    } else {
 46→      setCurrentIndex(nextIndex)
 47→      setTextComplete(false)
 48→      setFeedback(null)
 49→    }
 50→  }, [currentIndex, nodes.length])
 51→
 52→  const handleTextAreaClick = useCallback(() => {
 53→    if (feedback) return
 54→
 55→    if (!textComplete) {
 56→      // TypewriterText handles skip internally via its own onClick
 57→      return
 58→    }
 59→
 60→    // If no choices on this node, advance
 61→    if (!currentNode?.choices || currentNode.choices.length === 0) {
 62→      advanceToNext()
 63→    }
 64→  }, [textComplete, feedback, currentNode, advanceToNext])
 65→
 66→  const handleChoice = useCallback(
 67→    (choice: DialogueChoice) => {
 68→      if (choice.correct) {
 69→        setCorrectCount((prev) => prev + 1)
 70→        setFeedback({ type: 'correct', response: choice.response })
 71→
 72→        // Auto-advance after showing correct feedback
 73→        setTimeout(() => {
 74→          if (choice.nextNodeIndex !== undefined) {
 75→            setCurrentIndex(choice.nextNodeIndex)
 76→            setTextComplete(false)
 77→            setFeedback(null)
 78→          } else {
 79→            advanceToNext()
 80→          }
 81→        }, 1200)
 82→      } else {
 83→        setFeedback({ type: 'wrong', response: choice.response })
 84→
 85→        // Auto-advance after showing wrong feedback
 86→        setTimeout(() => {
 87→          if (choice.nextNodeIndex !== undefined) {
 88→            setCurrentIndex(choice.nextNodeIndex)
 89→            setTextComplete(false)
 90→            setFeedback(null)
 91→          } else {
 92→            advanceToNext()
 93→          }
 94→        }, 2000)
 95→      }
 96→    },
 97→    [advanceToNext]
 98→  )
 99→
100→  const handleComplete = useCallback(() => {
101→    const score = totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 100) : 100
102→    onComplete(score)
103→  }, [correctCount, totalQuestions, onComplete])
104→
105→  const handleTextComplete = useCallback(() => {
106→    setTextComplete(true)
107→  }, [])
108→
109→  // Summary screen
110→  if (showSummary) {
111→    return (
112→      <AnimatePresence>
113→        <motion.div
114→          className={clsx(
115→            'fixed inset-0 z-50 flex items-center justify-center bg-void/80 backdrop-blur-sm',
116→            className
117→          )}
118→          initial={{ opacity: 0 }}
119→          animate={{ opacity: 1 }}
120→          exit={{ opacity: 0 }}
121→          transition={{ duration: 0.3 }}
122→        >
123→          <motion.div
124→            initial={{ opacity: 0, y: 30 }}
125→            animate={{ opacity: 1, y: 0 }}
126→            transition={{ type: 'spring' as const, stiffness: 300, damping: 25, delay: 0.1 }}
127→          >
128→            <GlassPanel className="max-w-md w-full mx-4 text-center" padding="lg" glow="nebula">
129→              <h2 className="font-display text-2xl text-starlight mb-4 uppercase tracking-wider">
130→                Dialogue Complete
131→              </h2>
132→
133→              {totalQuestions > 0 ? (
134→                <>
135→                  <div className="mb-6">
136→                    <div className="font-mono text-4xl text-nebula mb-2">
137→                      {correctCount}/{totalQuestions}
138→                    </div>
139→                    <div className="font-body text-starlight-dim text-sm">
140→                      correct answers
141→                    </div>
142→                  </div>
143→
144→                  <div className="w-full bg-glass rounded-full h-2 mb-6">
145→                    <motion.div
146→                      className={clsx(
147→                        'h-2 rounded-full',
148→                        correctCount === totalQuestions ? 'bg-signal' : 'bg-nebula'
149→                      )}
150→                      initial={{ width: 0 }}
151→                      animate={{
152→                        width: `${totalQuestions > 0 ? (correctCount / totalQuestions) * 100 : 100}%`,
153→                      }}
154→                      transition={{ duration: 0.8, ease: 'easeOut', delay: 0.3 }}
155→                    />
156→                  </div>
157→
158→                  <p className="font-body text-starlight-dim text-sm mb-6">
159→                    {correctCount === totalQuestions
160→                      ? 'Perfect score! Outstanding work, Commander.'
161→                      : correctCount >= totalQuestions * 0.5
162→                        ? 'Good effort. Keep learning and try again.'
163→                        : 'There is more to learn. Review and try again.'}
164→                  </p>
165→                </>
166→              ) : (
167→                <p className="font-body text-starlight-dim text-sm mb-6">
168→                  Briefing acknowledged.
169→                </p>
170→              )}
171→
172→              <Button variant="primary" size="md" onClick={handleComplete}>
173→                Continue
174→              </Button>
175→            </GlassPanel>
176→          </motion.div>
177→        </motion.div>
178→      </AnimatePresence>
179→    )
180→  }
181→
182→  // Guard against invalid index
183→  if (!currentNode) return null
184→
185→  const speakerColor = speaker?.color ?? '#4a6fa5'
186→  const speakerName = speaker?.name ?? currentNode.speaker
187→  const speakerRole = speaker?.role ?? 'Unknown'
188→  const speakerInitial = speakerName.charAt(0).toUpperCase()
189→  const hasChoices = currentNode.choices && currentNode.choices.length > 0
190→
191→  return (
192→    <AnimatePresence>
193→      <motion.div
194→        className={clsx(
195→          'fixed inset-0 z-50 flex items-center justify-center bg-void/80 backdrop-blur-sm',
196→          className
197→        )}
198→        initial={{ opacity: 0 }}
199→        animate={{ opacity: 1 }}
200→        exit={{ opacity: 0 }}
201→        transition={{ duration: 0.3 }}
202→      >
203→        <motion.div
204→          className="w-full max-w-2xl mx-4"
205→          initial={{ opacity: 0, y: 30 }}
206→          animate={{ opacity: 1, y: 0 }}
207→          exit={{ opacity: 0, y: 30 }}
208→          transition={{ type: 'spring' as const, stiffness: 300, damping: 25, delay: 0.1 }}
209→        >
210→          <GlassPanel padding="lg" glow="nebula">
211→            {/* Speaker info */}
212→            <div className="flex items-center gap-3 mb-5">
213→              <div
214→                className="w-10 h-10 rounded-full flex items-center justify-center font-display text-lg text-void font-bold shrink-0"
215→                style={{ backgroundColor: speakerColor }}
216→              >
217→                {speakerInitial}
218→              </div>
219→              <div>
220→                <div className="font-display text-starlight text-sm uppercase tracking-wider">
221→                  {speakerName}
222→                </div>
223→                <div className="font-body text-starlight-dim text-xs">
224→                  {speakerRole}
225→                </div>
226→              </div>
227→            </div>
228→
229→            {/* Text area */}
230→            <div
231→              className={clsx(
232→                'min-h-[80px] mb-5 cursor-pointer select-none',
233→                !hasChoices && textComplete && 'hover:opacity-80'
234→              )}
235→              onClick={handleTextAreaClick}
236→              role="button"
237→              tabIndex={0}
238→              onKeyDown={(e) => {
239→                if (e.key === 'Enter' || e.key === ' ') {
240→                  handleTextAreaClick()
241→                }
242→              }}
243→            >
244→              <TypewriterText
245→                key={`${currentIndex}-${currentNode.text}`}
246→                text={currentNode.text}
247→                speed={25}
248→                className="font-body text-starlight text-base leading-relaxed"
249→                onComplete={handleTextComplete}
250→              />
251→
252→              {/* Advance hint */}
253→              {textComplete && !hasChoices && !feedback && (
254→                <motion.div
255→                  className="mt-3 font-body text-starlight-dim text-xs text-right"
256→                  initial={{ opacity: 0 }}
257→                  animate={{ opacity: 1 }}
258→                  transition={{ delay: 0.3 }}
259→                >
260→                  Click to continue...
261→                </motion.div>
262→              )}
263→            </div>
264→
265→            {/* Feedback flash */}
266→            <AnimatePresence>
267→              {feedback && (
268→                <motion.div
269→                  className={clsx(
270→                    'rounded-lg px-4 py-3 mb-4 font-body text-sm',
271→                    feedback.type === 'correct'
272→                      ? 'bg-signal/20 border border-signal/40 text-signal'
273→                      : 'bg-terracotta/20 border border-terracotta/40 text-terracotta'
274→                  )}
275→                  initial={{ opacity: 0, y: -8 }}
276→                  animate={{ opacity: 1, y: 0 }}
277→                  exit={{ opacity: 0, y: -8 }}
278→                  transition={{ type: 'spring' as const, stiffness: 400, damping: 25 }}
279→                >
280→                  <span className="font-display text-xs uppercase tracking-wider mr-2">
281→                    {feedback.type === 'correct' ? 'Correct' : 'Not quite'}
282→                  </span>
283→                  {feedback.response && (
284→                    <span className="text-starlight-dim">{feedback.response}</span>
285→                  )}
286→                </motion.div>
287→              )}
288→            </AnimatePresence>
289→
290→            {/* Choice buttons */}
291→            <AnimatePresence>
292→              {textComplete && hasChoices && !feedback && (
293→                <motion.div
294→                  className="flex flex-col gap-2"
295→                  initial={{ opacity: 0, y: 10 }}
296→                  animate={{ opacity: 1, y: 0 }}
297→                  exit={{ opacity: 0 }}
298→                  transition={{ type: 'spring' as const, stiffness: 300, damping: 25, delay: 0.15 }}
299→                >
300→                  {currentNode.choices!.map((choice, i) => (
301→                    <Button
302→                      key={`choice-${currentIndex}-${i}`}
303→                      variant="secondary"
304→                      size="sm"
305→                      onClick={() => handleChoice(choice)}
306→                      className="text-left normal-case tracking-normal font-body w-full justify-start"
307→                    >
308→                      <span className="font-mono text-nebula mr-2 text-xs">
309→                        {String.fromCharCode(65 + i)}.
310→                      </span>
311→                      {choice.text}
312→                    </Button>
313→                  ))}
314→                </motion.div>
315→              )}
316→            </AnimatePresence>
317→
318→            {/* Progress indicator */}
319→            <div className="mt-5 flex items-center justify-between">
320→              <div className="font-mono text-starlight-dim text-xs">
321→                {currentIndex + 1} / {nodes.length}
322→              </div>
323→              {totalQuestions > 0 && (
324→                <div className="font-mono text-starlight-dim text-xs">
325→                  Score: {correctCount}/{totalQuestions}
326→                </div>
327→              )}
328→            </div>
329→          </GlassPanel>
330→        </motion.div>
331→      </motion.div>
332→    </AnimatePresence>
333→  )
334→}
