  1→'use client'
  2→
  3→import { useState } from 'react'
  4→import { motion, AnimatePresence } from 'motion/react'
  5→import { clsx } from 'clsx'
  6→import { GlassPanel } from '@/components/ui/GlassPanel'
  7→import { Button } from '@/components/ui/Button'
  8→
  9→interface DebugProps {
 10→  code: string
 11→  bugLines: number[]
 12→  explanations: Record<number, string>
 13→  onComplete: (score: number) => void
 14→  className?: string
 15→}
 16→
 17→type Phase = 'input' | 'results'
 18→
 19→interface LineResult {
 20→  lineNumber: number
 21→  text: string
 22→  status: 'correct' | 'false-positive' | 'missed' | 'neutral'
 23→  explanation?: string
 24→}
 25→
 26→export function Debug({ code, bugLines, explanations, onComplete, className }: DebugProps) {
 27→  const [selectedLines, setSelectedLines] = useState<Set<number>>(new Set())
 28→  const [phase, setPhase] = useState<Phase>('input')
 29→  const [score, setScore] = useState(0)
 30→  const [lineResults, setLineResults] = useState<LineResult[]>([])
 31→
 32→  const lines = code.split('\n')
 33→
 34→  function toggleLine(lineNumber: number) {
 35→    setSelectedLines((prev) => {
 36→      const next = new Set(prev)
 37→      if (next.has(lineNumber)) {
 38→        next.delete(lineNumber)
 39→      } else {
 40→        next.add(lineNumber)
 41→      }
 42→      return next
 43→    })
 44→  }
 45→
 46→  function handleSubmit() {
 47→    const correctSelections = [...selectedLines].filter((ln) => bugLines.includes(ln)).length
 48→    const falsePositives = [...selectedLines].filter((ln) => !bugLines.includes(ln)).length
 49→    const computed = Math.max(0, Math.round(((correctSelections - falsePositives) / bugLines.length) * 100))
 50→
 51→    setScore(computed)
 52→
 53→    const results: LineResult[] = lines.map((text, i) => {
 54→      const lineNumber = i + 1
 55→      const isBug = bugLines.includes(lineNumber)
 56→      const isSelected = selectedLines.has(lineNumber)
 57→
 58→      if (isSelected && isBug) {
 59→        return { lineNumber, text, status: 'correct' as const, explanation: explanations[lineNumber] }
 60→      }
 61→      if (isSelected && !isBug) {
 62→        return { lineNumber, text, status: 'false-positive' as const }
 63→      }
 64→      if (!isSelected && isBug) {
 65→        return { lineNumber, text, status: 'missed' as const, explanation: explanations[lineNumber] }
 66→      }
 67→      return { lineNumber, text, status: 'neutral' as const }
 68→    })
 69→
 70→    setLineResults(results)
 71→    setPhase('results')
 72→  }
 73→
 74→  return (
 75→    <motion.div
 76→      initial={{ opacity: 0, y: 20 }}
 77→      animate={{ opacity: 1, y: 0 }}
 78→      transition={{ type: 'spring' as const, stiffness: 300, damping: 25 }}
 79→      className={clsx('w-full max-w-2xl mx-auto', className)}
 80→    >
 81→      <GlassPanel padding="lg">
 82→        <AnimatePresence mode="wait">
 83→          {phase === 'input' && (
 84→            <motion.div
 85→              key="input"
 86→              initial={{ opacity: 0, y: 10 }}
 87→              animate={{ opacity: 1, y: 0 }}
 88→              exit={{ opacity: 0, y: -10 }}
 89→              transition={{ type: 'spring' as const, stiffness: 300, damping: 25 }}
 90→              className="space-y-5"
 91→            >
 92→              {/* Header */}
 93→              <h3 className="font-display text-lg text-nebula uppercase tracking-wider">
 94→                Debug Scanner
 95→              </h3>
 96→
 97→              {/* Instructions */}
 98→              <p className="font-body text-sm text-starlight-dim leading-relaxed">
 99→                Find the bugs in this code. Click on the lines you think contain issues.
100→              </p>
101→
102→              {/* Code Display */}
103→              <div className="bg-void/50 border border-glass-border rounded-lg overflow-hidden">
104→                <div className="max-h-[50vh] overflow-y-auto scrollbar-thin">
105→                  {lines.map((line, i) => {
106→                    const lineNumber = i + 1
107→                    const isSelected = selectedLines.has(lineNumber)
108→
109→                    return (
110→                      <motion.button
111→                        key={lineNumber}
112→                        type="button"
113→                        onClick={() => toggleLine(lineNumber)}
114→                        className={clsx(
115→                          'w-full flex items-start text-left transition-colors',
116→                          'hover:bg-glass',
117→                          isSelected && 'border-l-2 border-terracotta bg-terracotta/10',
118→                          !isSelected && 'border-l-2 border-transparent'
119→                        )}
120→                        whileTap={{ scale: 0.995 }}
121→                      >
122→                        <span
123→                          className={clsx(
124→                            'flex-shrink-0 w-10 text-right pr-3 py-1',
125→                            'font-mono text-xs text-starlight-dim select-none'
126→                          )}
127→                        >
128→                          {lineNumber}
129→                        </span>
130→                        <span className="font-mono text-sm text-starlight py-1 pr-4 whitespace-pre">
131→                          {line}
132→                        </span>
133→                      </motion.button>
134→                    )
135→                  })}
136→                </div>
137→              </div>
138→
139→              {/* Selection count */}
140→              <p className="font-body text-sm text-starlight-dim">
141→                {selectedLines.size} {selectedLines.size === 1 ? 'line' : 'lines'} selected
142→              </p>
143→
144→              {/* Submit */}
145→              <Button
146→                onClick={handleSubmit}
147→                disabled={selectedLines.size === 0}
148→                variant="primary"
149→                size="lg"
150→                className="w-full"
151→              >
152→                Submit Analysis
153→              </Button>
154→            </motion.div>
155→          )}
156→
157→          {phase === 'results' && (
158→            <motion.div
159→              key="results"
160→              initial={{ opacity: 0, y: 10 }}
161→              animate={{ opacity: 1, y: 0 }}
162→              exit={{ opacity: 0, y: -10 }}
163→              transition={{ type: 'spring' as const, stiffness: 300, damping: 25 }}
164→              className="space-y-5"
165→            >
166→              {/* Header */}
167→              <h3 className="font-display text-lg text-nebula uppercase tracking-wider">
168→                Analysis Results
169→              </h3>
170→
171→              {/* Score */}
172→              <div className="text-center py-3">
173→                <motion.span
174→                  initial={{ scale: 0.5, opacity: 0 }}
175→                  animate={{ scale: 1, opacity: 1 }}
176→                  transition={{ type: 'spring' as const, stiffness: 300, damping: 20, delay: 0.2 }}
177→                  className={clsx(
178→                    'font-display text-4xl',
179→                    score >= 80 && 'text-signal',
180→                    score >= 40 && score < 80 && 'text-nebula',
181→                    score < 40 && 'text-terracotta'
182→                  )}
183→                >
184→                  {score}%
185→                </motion.span>
186→              </div>
187→
188→              {/* Results breakdown */}
189→              <div className="bg-void/50 border border-glass-border rounded-lg overflow-hidden">
190→                <div className="max-h-[50vh] overflow-y-auto scrollbar-thin">
191→                  {lineResults.map((result, i) => (
192→                    <motion.div
193→                      key={result.lineNumber}
194→                      initial={{ opacity: 0, x: -5 }}
195→                      animate={{ opacity: 1, x: 0 }}
196→                      transition={{
197→                        type: 'spring' as const,
198→                        stiffness: 300,
199→                        damping: 25,
200→                        delay: i * 0.02,
201→                      }}
202→                      className={clsx(
203→                        'border-l-2',
204→                        result.status === 'correct' && 'border-signal bg-signal/5',
205→                        result.status === 'false-positive' && 'border-terracotta bg-terracotta/5',
206→                        result.status === 'missed' && 'border-amber-400 bg-amber-400/5',
207→                        result.status === 'neutral' && 'border-transparent'
208→                      )}
209→                    >
210→                      {/* Code line */}
211→                      <div className="flex items-start">
212→                        <span className="flex-shrink-0 w-10 text-right pr-3 py-1 font-mono text-xs text-starlight-dim select-none">
213→                          {result.lineNumber}
214→                        </span>
215→
216→                        {result.status !== 'neutral' && (
217→                          <span
218→                            className={clsx(
219→                              'flex-shrink-0 w-5 py-1 font-mono text-sm font-bold',
220→                              result.status === 'correct' && 'text-signal',
221→                              result.status === 'false-positive' && 'text-terracotta',
222→                              result.status === 'missed' && 'text-amber-400'
223→                            )}
224→                          >
225→                            {result.status === 'correct' && '\u2713'}
226→                            {result.status === 'false-positive' && '\u2717'}
227→                            {result.status === 'missed' && '!'}
228→                          </span>
229→                        )}
230→
231→                        <span
232→                          className={clsx(
233→                            'font-mono text-sm py-1 pr-4 whitespace-pre',
234→                            result.status === 'neutral' ? 'text-starlight-dim' : 'text-starlight'
235→                          )}
236→                        >
237→                          {result.text}
238→                        </span>
239→                      </div>
240→
241→                      {/* Explanation */}
242→                      {result.status === 'correct' && result.explanation && (
243→                        <div className="ml-[3.75rem] pb-2 pr-4">
244→                          <span className="font-body text-xs text-signal">
245→                            {result.explanation}
246→                          </span>
247→                        </div>
248→                      )}
249→                      {result.status === 'false-positive' && (
250→                        <div className="ml-[3.75rem] pb-2 pr-4">
251→                          <span className="font-body text-xs text-terracotta">
252→                            No bug here
253→                          </span>
254→                        </div>
255→                      )}
