  7→
  8→export interface TaskItem {
  9→  id: string
 10→  label: string
 11→  description: string
 12→}
 13→
 14→export interface AgentItem {
 15→  id: string
 16→  label: string
 17→  specialty: string
 18→}
 19→
 20→export interface CommandProps {
 21→  tasks: TaskItem[]
 22→  agents: AgentItem[]
 23→  correctAssignments: Record<string, string>
 24→  onComplete: (score: number) => void
 25→  className?: string
 26→}
 27→
 28→interface AssignmentResult {
 29→  taskId: string
 30→  assignedAgentId: string
 31→  correctAgentId: string
 32→  isCorrect: boolean
 33→}
 34→
 35→const springTransition = { type: 'spring' as const, stiffness: 400, damping: 25 }
 36→
 37→export function Command({ tasks, agents, correctAssignments, onComplete, className }: CommandProps) {
 38→  const [assignments, setAssignments] = useState<Record<string, string>>({})
 39→  const [selectedAgentId, setSelectedAgentId] = useState<string | null>(null)
 40→  const [checked, setChecked] = useState(false)
 41→  const [results, setResults] = useState<AssignmentResult[]>([])
 42→  const [score, setScore] = useState(0)
 43→  const [draggedAgentId, setDraggedAgentId] = useState<string | null>(null)
 44→  const taskRefs = useRef<Map<string, HTMLDivElement>>(new Map())
 45→
 46→  const allAssigned = tasks.every((task) => assignments[task.id])
 47→
 48→  const getAssignedAgent = useCallback(
 49→    (taskId: string): AgentItem | undefined => {
 50→      const agentId = assignments[taskId]
 51→      return agentId ? agents.find((a) => a.id === agentId) : undefined
 52→    },
 53→    [assignments, agents]
 54→  )
 55→
 56→  const isAgentAssigned = useCallback(
 57→    (agentId: string): boolean => {
 58→      return Object.values(assignments).includes(agentId)
 59→    },
 60→    [assignments]
 61→  )
 62→
 63→  function assignAgent(taskId: string, agentId: string) {
 64→    setAssignments((prev) => {
 65→      const next = { ...prev }
 66→
 67→      // If this agent is already assigned elsewhere, remove that assignment
 68→      for (const [tid, aid] of Object.entries(next)) {
 69→        if (aid === agentId) {
 70→          delete next[tid]
 71→        }
 72→      }
 73→
 74→      // If this task already has an agent, that agent returns to pool (just overwrite)
 75→      next[taskId] = agentId
 76→
 77→      return next
 78→    })
 79→  }
 80→
 81→  function handleTaskClick(taskId: string) {
 82→    if (checked) return
 83→
 84→    if (selectedAgentId) {
 85→      assignAgent(taskId, selectedAgentId)
 86→      setSelectedAgentId(null)
 87→    }
 88→  }
 89→
 90→  function handleAgentClick(agentId: string) {
 91→    if (checked) return
 92→
 93→    if (selectedAgentId === agentId) {
 94→      setSelectedAgentId(null)
 95→    } else {
 96→      setSelectedAgentId(agentId)
 97→    }
 98→  }
 99→
100→  function handleDragEnd(agentId: string, event: PointerEvent) {
101→    setDraggedAgentId(null)
102→
103→    // Find which task card the pointer is over
104→    const x = event.clientX
105→    const y = event.clientY
106→
107→    for (const [taskId, el] of taskRefs.current.entries()) {
108→      const rect = el.getBoundingClientRect()
109→      if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) {
110→        assignAgent(taskId, agentId)
111→        return
112→      }
113→    }
114→  }
115→
116→  function handleCheck() {
117→    const assignmentResults: AssignmentResult[] = tasks.map((task) => ({
118→      taskId: task.id,
119→      assignedAgentId: assignments[task.id],
120→      correctAgentId: correctAssignments[task.id],
121→      isCorrect: assignments[task.id] === correctAssignments[task.id],
122→    }))
123→
124→    const correct = assignmentResults.filter((r) => r.isCorrect).length
125→    const calculatedScore = Math.round((correct / tasks.length) * 100)
126→
127→    setResults(assignmentResults)
128→    setScore(calculatedScore)
129→    setChecked(true)
130→  }
131→
132→  function getTaskResult(taskId: string): AssignmentResult | undefined {
133→    return results.find((r) => r.taskId === taskId)
134→  }
135→
136→  function getCorrectAgentLabel(taskId: string): string {
137→    const correctId = correctAssignments[taskId]
138→    const agent = agents.find((a) => a.id === correctId)
139→    return agent?.label ?? 'Unknown'
140→  }
141→
142→  return (
143→    <GlassPanel className={clsx('max-w-3xl w-full', className)} padding="lg">
144→      <AnimatePresence mode="wait">
145→        {!checked ? (
146→          <motion.div
147→            key="assignment"
148→            initial={{ opacity: 0, y: 12 }}
149→            animate={{ opacity: 1, y: 0 }}
150→            exit={{ opacity: 0, y: -12 }}
151→            transition={springTransition}
152→          >
153→            <h3 className="font-display text-xl text-starlight mb-2 uppercase tracking-wider">
154→              Command Center
155→            </h3>
156→            <p className="font-body text-sm text-starlight-dim leading-relaxed mb-6">
157→              Assign each agent to the task that matches their specialty.
158→              {' '}
159→              <span className="text-starlight-dim/60">
160→                Drag agents to tasks, or tap an agent then tap a task.
161→              </span>
162→            </p>
163→
164→            {/* Task cards grid */}
165→            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-8">
166→              {tasks.map((task, index) => {
