 7→interface ButtonProps {
 8→  children: React.ReactNode
 9→  variant?: 'primary' | 'secondary' | 'danger' | 'success' | 'ghost'
10→  size?: 'sm' | 'md' | 'lg'
11→  disabled?: boolean
12→  onClick?: () => void
13→  className?: string
14→  type?: 'button' | 'submit'
15→}
16→
17→const variantStyles = {
18→  primary: 'bg-nebula/20 border-nebula/40 text-nebula hover:bg-nebula/30 hover:border-nebula/60',
19→  secondary: 'bg-glass border-glass-border text-starlight hover:bg-glass-hover',
20→  danger: 'bg-terracotta/20 border-terracotta/40 text-terracotta hover:bg-terracotta/30',
21→  success: 'bg-signal/20 border-signal/40 text-signal hover:bg-signal/30',
22→  ghost: 'bg-transparent border-transparent text-starlight-dim hover:text-starlight hover:bg-glass',
23→}
24→
25→const sizeStyles = {
26→  sm: 'px-3 py-1.5 text-sm',
27→  md: 'px-5 py-2.5 text-base',
28→  lg: 'px-8 py-3.5 text-lg',
29→}
30→
31→export function Button({ children, variant = 'primary', size = 'md', disabled, onClick, className, type = 'button' }: ButtonProps) {
32→  const { playSFX } = useAudio()
33→
34→  const handleClick = () => {
35→    if (!disabled) {
36→      playSFX('click')
37→    }
38→    onClick?.()
39→  }
40→
41→  return (
42→    <motion.button
43→      type={type}
44→      onClick={handleClick}
45→      disabled={disabled}
46→      className={clsx(
47→        'font-display uppercase tracking-wider border rounded-xl backdrop-blur-sm transition-colors',
48→        'focus:outline-none focus-visible:ring-2 focus-visible:ring-nebula/50',
49→        variantStyles[variant],
50→        sizeStyles[size],
51→        disabled && 'opacity-40 cursor-not-allowed',
52→        className
53→      )}
54→      whileHover={disabled ? undefined : { scale: 1.03 }}
55→      whileTap={disabled ? undefined : { scale: 0.97 }}
56→      transition={{ type: 'spring', stiffness: 400, damping: 25 }}
57→    >
58→      {children}
59→    </motion.button>
60→  )
61→}
