  1→'use client'
  2→
  3→import { useState, useCallback, useRef } from 'react'
  4→import { motion, AnimatePresence } from 'motion/react'
  5→import { clsx } from 'clsx'
  6→import { GlassPanel, Button } from '@/components/ui'
  7→import { useAudio } from '@/components/audio/AudioManager'
  8→
  9→export interface TaskItem {
 10→  id: string
 11→  label: string
 12→  description: string
 13→}
 14→
 15→export interface AgentItem {
 16→  id: string
 17→  label: string
 18→  specialty: string
 19→}
 20→
 21→export interface CommandProps {
 22→  tasks: TaskItem[]
 23→  agents: AgentItem[]
 24→  correctAssignments: Record<string, string>
 25→  onComplete: (score: number) => void
 26→  className?: string
 27→}
 28→
 29→interface AssignmentResult {
 30→  taskId: string
 31→  assignedAgentId: string
 32→  correctAgentId: string
 33→  isCorrect: boolean
 34→}
 35→
 36→const springTransition = { type: 'spring' as const, stiffness: 400, damping: 25 }
 37→
 38→export function Command({ tasks, agents, correctAssignments, onComplete, className }: CommandProps) {
 39→  const { playSFX } = useAudio()
 40→  const [assignments, setAssignments] = useState<Record<string, string>>({})
 41→  const [selectedAgentId, setSelectedAgentId] = useState<string | null>(null)
 42→  const [checked, setChecked] = useState(false)
 43→  const [results, setResults] = useState<AssignmentResult[]>([])
 44→  const [score, setScore] = useState(0)
 45→  const [draggedAgentId, setDraggedAgentId] = useState<string | null>(null)
 46→  const taskRefs = useRef<Map<string, HTMLDivElement>>(new Map())
 47→
 48→  const allAssigned = tasks.every((task) => assignments[task.id])
 49→
 50→  const getAssignedAgent = useCallback(
 51→    (taskId: string): AgentItem | undefined => {
 52→      const agentId = assignments[taskId]
 53→      return agentId ? agents.find((a) => a.id === agentId) : undefined
 54→    },
 55→    [assignments, agents]
 56→  )
 57→
 58→  const isAgentAssigned = useCallback(
 59→    (agentId: string): boolean => {
 60→      return Object.values(assignments).includes(agentId)
 61→    },
 62→    [assignments]
 63→  )
 64→
 65→  function assignAgent(taskId: string, agentId: string) {
 66→    setAssignments((prev) => {
 67→      const next = { ...prev }
 68→
 69→      // If this agent is already assigned elsewhere, remove that assignment
 70→      for (const [tid, aid] of Object.entries(next)) {
 71→        if (aid === agentId) {
 72→          delete next[tid]
 73→        }
 74→      }
 75→
 76→      // If this task already has an agent, that agent returns to pool (just overwrite)
 77→      next[taskId] = agentId
 78→
 79→      return next
 80→    })
 81→  }
 82→
 83→  function handleTaskClick(taskId: string) {
 84→    if (checked) return
 85→
 86→    if (selectedAgentId) {
 87→      assignAgent(taskId, selectedAgentId)
 88→      setSelectedAgentId(null)
 89→      playSFX('click')
 90→    }
 91→  }
 92→
 93→  function handleAgentClick(agentId: string) {
 94→    if (checked) return
 95→
 96→    if (selectedAgentId === agentId) {
 97→      setSelectedAgentId(null)
 98→    } else {
 99→      setSelectedAgentId(agentId)
100→    }
101→  }
102→
103→  function handleDragEnd(agentId: string, event: PointerEvent) {
104→    setDraggedAgentId(null)
105→
106→    // Find which task card the pointer is over
107→    const x = event.clientX
108→    const y = event.clientY
109→
110→    for (const [taskId, el] of taskRefs.current.entries()) {
111→      const rect = el.getBoundingClientRect()
112→      if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) {
113→        assignAgent(taskId, agentId)
114→        return
115→      }
116→    }
117→  }
118→
119→  function handleCheck() {
120→    const assignmentResults: AssignmentResult[] = tasks.map((task) => ({
121→      taskId: task.id,
122→      assignedAgentId: assignments[task.id],
123→      correctAgentId: correctAssignments[task.id],
124→      isCorrect: assignments[task.id] === correctAssignments[task.id],
125→    }))
126→
127→    const correct = assignmentResults.filter((r) => r.isCorrect).length
128→    const calculatedScore = Math.round((correct / tasks.length) * 100)
129→
130→    setResults(assignmentResults)
131→    setScore(calculatedScore)
132→    setChecked(true)
133→    playSFX(calculatedScore >= 70 ? 'success' : 'error')
134→  }
135→
136→  function getTaskResult(taskId: string): AssignmentResult | undefined {
137→    return results.find((r) => r.taskId === taskId)
138→  }
139→
140→  function getCorrectAgentLabel(taskId: string): string {
141→    const correctId = correctAssignments[taskId]
142→    const agent = agents.find((a) => a.id === correctId)
143→    return agent?.label ?? 'Unknown'
144→  }
145→
146→  return (
147→    <GlassPanel className={clsx('max-w-3xl w-full', className)} padding="lg">
148→      <AnimatePresence mode="wait">
149→        {!checked ? (
150→          <motion.div
151→            key="assignment"
152→            initial={{ opacity: 0, y: 12 }}
153→            animate={{ opacity: 1, y: 0 }}
154→            exit={{ opacity: 0, y: -12 }}
155→            transition={springTransition}
156→          >
157→            <h3 className="font-display text-xl text-starlight mb-2 uppercase tracking-wider">
158→              Command Center
159→            </h3>
160→            <p className="font-body text-sm text-starlight-dim leading-relaxed mb-6">
161→              Assign each agent to the task that matches their specialty.
162→              {' '}
163→              <span className="text-starlight-dim/60">
164→                Drag agents to tasks, or tap an agent then tap a task.
165→              </span>
166→            </p>
167→
168→            {/* Task cards grid */}
169→            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-8">
170→              {tasks.map((task, index) => {
171→                const assignedAgent = getAssignedAgent(task.id)
172→                const isDropTarget = selectedAgentId !== null || draggedAgentId !== null
173→
174→                return (
175→                  <motion.div
176→                    key={task.id}
177→                    ref={(el) => {
178→                      if (el) taskRefs.current.set(task.id, el)
179→                    }}
180→                    initial={{ opacity: 0, y: 8 }}
181→                    animate={{ opacity: 1, y: 0 }}
182→                    transition={{ ...springTransition, delay: index * 0.05 }}
183→                    onClick={() => handleTaskClick(task.id)}
184→                    className={clsx(
185→                      'bg-void/40 border rounded-xl p-4 transition-colors cursor-pointer',
186→                      isDropTarget
187→                        ? 'border-nebula/40 shadow-glow-nebula/20'
188→                        : 'border-glass-border',
189→                      'hover:border-nebula/30'
190→                    )}
191→                  >
192→                    <p className="font-display text-sm text-starlight uppercase tracking-wider mb-1">
193→                      {task.label}
194→                    </p>
195→                    <p className="font-body text-xs text-starlight-dim leading-relaxed mb-3">
196→                      {task.description}
197→                    </p>
198→
199→                    {/* Assignment slot */}
200→                    <div
201→                      className={clsx(
202→                        'h-9 rounded-lg border border-dashed flex items-center justify-center transition-colors',
203→                        assignedAgent
204→                          ? 'border-nebula/50 bg-nebula/10'
205→                          : 'border-glass-border bg-void/20'
206→                      )}
207→                    >
208→                      <AnimatePresence mode="wait">
209→                        {assignedAgent ? (
210→                          <motion.span
211→                            key={assignedAgent.id}
212→                            initial={{ opacity: 0, scale: 0.8 }}
213→                            animate={{ opacity: 1, scale: 1 }}
214→                            exit={{ opacity: 0, scale: 0.8 }}
215→                            transition={springTransition}
216→                            className="font-mono text-xs text-nebula px-3 py-1"
217→                          >
218→                            {assignedAgent.label}
219→                          </motion.span>
220→                        ) : (
221→                          <motion.span
222→                            key="empty"
223→                            initial={{ opacity: 0 }}
224→                            animate={{ opacity: 0.4 }}
225→                            exit={{ opacity: 0 }}
226→                            className="font-mono text-xs text-starlight-dim"
227→                          >
228→                            Drop agent here
229→                          </motion.span>
230→                        )}
231→                      </AnimatePresence>
232→                    </div>
233→                  </motion.div>
234→                )
235→              })}
236→            </div>
237→
238→            {/* Agent tokens */}
239→            <div className="mb-6">
240→              <p className="font-mono text-xs text-starlight-dim uppercase tracking-wider mb-3">
241→                Available Agents
242→              </p>
243→              <div className="flex flex-wrap gap-2">
244→                {agents.map((agent, index) => {
245→                  const assigned = isAgentAssigned(agent.id)
246→                  const selected = selectedAgentId === agent.id
247→
248→                  return (
249→                    <motion.div
250→                      key={agent.id}
251→                      drag
252→                      dragSnapToOrigin
253→                      onDragStart={() => setDraggedAgentId(agent.id)}
254→                      onDragEnd={(event) =>
255→                        handleDragEnd(agent.id, event as unknown as PointerEvent)
256→                      }
257→                      whileDrag={{ scale: 1.1, zIndex: 50 }}
258→                      onClick={() => handleAgentClick(agent.id)}
259→                      initial={{ opacity: 0, y: 8 }}
260→                      animate={{
261→                        opacity: assigned ? 0.4 : 1,
262→                        y: 0,
263→                        scale: selected ? 1.05 : 1,
264→                      }}
265→                      transition={{ ...springTransition, delay: index * 0.03 }}
266→                      className={clsx(
267→                        'flex flex-col rounded-lg border px-3 py-2 cursor-grab active:cursor-grabbing select-none',
268→                        'transition-colors',
269→                        selected
270→                          ? 'border-nebula bg-nebula/20 shadow-glow-nebula'
271→                          : assigned
272→                            ? 'border-glass-border/50 bg-void/30'
273→                            : 'border-glass-border bg-glass hover:border-nebula/40',
274→                        'focus:outline-none focus-visible:ring-2 focus-visible:ring-nebula/50'
275→                      )}
276→                      tabIndex={0}
277→                      onKeyDown={(e) => {
278→                        if (e.key === 'Enter' || e.key === ' ') {
279→                          e.preventDefault()
280→                          handleAgentClick(agent.id)
281→                        }
282→                      }}
283→                    >
284→                      <span className="font-display text-xs text-starlight uppercase tracking-wider">
285→                        {agent.label}
286→                      </span>
287→                      <span className="font-mono text-[10px] text-starlight-dim leading-tight">
288→                        {agent.specialty}
289→                      </span>
290→                    </motion.div>
291→                  )
292→                })}
293→              </div>
294→            </div>
295→
296→            <Button
297→              onClick={handleCheck}
298→              disabled={!allAssigned}
299→              variant="primary"
300→              size="md"
301→            >
302→              Check Assignments
303→            </Button>
304→          </motion.div>
305→        ) : (
306→          <motion.div
307→            key="results"
308→            initial={{ opacity: 0, y: 12 }}
309→            animate={{ opacity: 1, y: 0 }}
310→            exit={{ opacity: 0, y: -12 }}
311→            transition={springTransition}
312→          >
313→            <h3 className="font-display text-xl text-starlight mb-2 uppercase tracking-wider">
314→              Mission Report
315→            </h3>
316→
317→            <motion.p
318→              className={clsx(
319→                'font-display text-3xl mb-6 uppercase tracking-wider',
320→                score >= 80 ? 'text-signal' : score >= 50 ? 'text-nebula' : 'text-terracotta'
321→              )}
322→              initial={{ scale: 0.8, opacity: 0 }}
323→              animate={{ scale: 1, opacity: 1 }}
324→              transition={{ ...springTransition, delay: 0.1 }}
325→            >
326→              {score}%
327→            </motion.p>
328→
329→            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-6">
330→              {tasks.map((task, index) => {
331→                const result = getTaskResult(task.id)
332→                const assignedAgent = agents.find((a) => a.id === result?.assignedAgentId)
333→
334→                return (
335→                  <motion.div
336→                    key={task.id}
337→                    initial={{ opacity: 0, y: 8 }}
338→                    animate={{ opacity: 1, y: 0 }}
339→                    transition={{ ...springTransition, delay: 0.15 + index * 0.05 }}
340→                    className={clsx(
341→                      'bg-void/40 border rounded-xl p-4',
342→                      result?.isCorrect
343→                        ? 'border-signal/50'
344→                        : 'border-terracotta/50'
345→                    )}
346→                  >
347→                    <div className="flex items-start justify-between gap-2 mb-2">
348→                      <p className="font-display text-sm text-starlight uppercase tracking-wider">
349→                        {task.label}
350→                      </p>
351→                      <motion.span
352→                        initial={{ scale: 0 }}
353→                        animate={{ scale: 1 }}
354→                        transition={{ ...springTransition, delay: 0.3 + index * 0.05 }}
355→                        className={clsx(
356→                          'text-lg',
357→                          result?.isCorrect ? 'text-signal' : 'text-terracotta'
358→                        )}
359→                      >
360→                        {result?.isCorrect ? '\u2713' : '\u2717'}
361→                      </motion.span>
362→                    </div>
363→
364→                    <div
365→                      className={clsx(
366→                        'rounded-lg border px-3 py-1.5 mb-1',
367→                        result?.isCorrect
368→                          ? 'border-signal/30 bg-signal/10'
369→                          : 'border-terracotta/30 bg-terracotta/10'
370→                      )}
371→                    >
372→                      <span
373→                        className={clsx(
374→                          'font-mono text-xs',
375→                          result?.isCorrect ? 'text-signal' : 'text-terracotta'
376→                        )}
377→                      >
378→                        {assignedAgent?.label}
379→                      </span>
380→                    </div>
381→
382→                    {!result?.isCorrect && (
383→                      <motion.p
384→                        initial={{ opacity: 0 }}
385→                        animate={{ opacity: 1 }}
386→                        transition={{ delay: 0.4 + index * 0.05 }}
387→                        className="font-mono text-[10px] text-starlight-dim mt-1"
388→                      >
389→                        Correct: {getCorrectAgentLabel(task.id)}
390→                      </motion.p>
391→                    )}
392→                  </motion.div>
393→                )
394→              })}
395→            </div>
396→
397→            <Button
398→              onClick={() => onComplete(score)}
399→              variant="success"
400→              size="md"
401→            >
402→              Continue
403→            </Button>
404→          </motion.div>
405→        )}
406→      </AnimatePresence>
407→    </GlassPanel>
408→  )
409→}
